-- VHDL timed text simulation
use std.textio.all;
entity main is end entity;
architecture test of main is
begin
  process
    variable line_out : line;
  begin
    for n in 1 to 3 loop
      wait for 5 ns;
      write(line_out, string'("count="));
      write(line_out, n);
      writeline(output, line_out);
    end loop;
    wait;
  end process;
end architecture;

